# -*- coding: utf-8 -*-
import odoo
from odoo import api, SUPERUSER_ID

product_data = {'ES001': {'name': 'Uñas postizas degrade azul', 'price': 2.43, 'b64': ''}, 'ES015': {'name': 'Pinzas para cabello de bebe color pastel x par', 'price': 1.86, 'b64': ''}, 'ES003': {'name': 'Pestañas de media banda 3D x10 pares', 'price': 3.96, 'b64': ''}, 'ES007': {'name': 'Esponja de maquillaje ultrasuave', 'price': 1.2, 'b64': ''}, 'ES018': {'name': 'Cepillo versatil para limpieza de ranuras', 'price': 1.93, 'b64': ''}, 'ES013': {'name': 'Liguitas color gelatina en cartuchera x 1000pzas', 'price': 2.24, 'b64': ''}, 'ES011': {'name': 'Ligas de cabello 400 pza gruesas, alta elasticidad', 'price': 2.27, 'b64': ''}}

registry = odoo.modules.registry.Registry('said_express')
with registry.cursor() as cr:
    env = api.Environment(cr, SUPERUSER_ID, {})

    for code, info in product_data.items():
        products = env['product.product'].search([
            '|', '|', ('default_code', '=', code), ('barcode', '=', code), ('name', 'ilike', info['name'][:15])
        ])
        
        if products:
            for p in products:
                p.write({
                    'image_1920': info['b64'],
                    'default_code': p.default_code or code,
                    'barcode': p.barcode or code,
                })
                print(f"SUCCESS: UPDATED product ID {p.id}: {p.name} (Code: {code}) with image!")
        else:
            new_p = env['product.product'].create({
                'name': info['name'],
                'default_code': code,
                'barcode': code,
                'lst_price': info['price'],
                'is_storable': True,
                'image_1920': info['b64'],
            })
            print(f"SUCCESS: CREATED new product ID {new_p.id}: {new_p.name} (Code: {code}) with image!")

    cr.commit()
    print("ALL 7 PRODUCTS UPDATED SUCCESSFULLY WITH IMAGES IN SAID_EXPRESS DATABASE!")
